csui.define('nuc/utils/objectstorage',['nuc/lib/underscore'], function (_) {
  'use strict';

  function ObjectStorage() {
    this.items = {};
  }

  _.extend(ObjectStorage.prototype, {
    constructor: ObjectStorage,
    setItem: function (k, v) {
      this.items[k] = v;
    },

    getItem: function (k) {
      return this.items[k];
    },

    removeItem: function (k) {
      delete this.items[k];
    }
  });

  return ObjectStorage;
});
