csui.define('nuc/utils/authenticators/server.adaptors/basic.mixin',['nuc/lib/underscore', 'nuc/utils/url'], function (_, Url) {
  'use strict';

  var ServerAdaptorMixin = {
    mixin: function (prototype) {
      return _.extend(prototype, {
        makeServerAdaptor: function (_options) {
          return this;
        },

        prepareRequest: function (options) {
          // Allow calling the login() method directly with partial
          // request settings overriding the authenticator defaults.
          var credentials = (options && options.data) || this.connection.credentials;
          return {
            url: Url.combine(this.connection.url, 'auth'),
            headers: {
              authorization: this.formatAuthorizationHeader(credentials)
            }
          };
        }
      });
    }
  };

  return ServerAdaptorMixin;
});
